import {restoreAnalysisMetrics} from './backup-analysis.js';
import {restoreCheckpoint} from './review-checkpoint.js';
import {cleanRating} from './puzzle-rating.js';
import {TYPES} from './analysis.js';
import {sanitizeSettings} from './settings.js';
import {Chess} from './vendor/chess.js';
import {playUci} from './tactics.js';
const text=(s,max=300)=>typeof s==='string'&&s.length>0&&s.length<=max;
const number=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max;
export function validateBackup(data){if(data?.format!=='plystreak-backup'||![1,2].includes(data.version)||!Array.isArray(data.games)||data.games.length>50000)throw Error('Formato backup non valido.');const games=data.games.map(g=>{if(!text(g.id)||!text(g.pgn,1000000))throw Error('Partita nel backup non valida.');const c=new Chess();c.loadPgn(g.pgn);const moves=c.history({verbose:true});let analysis;
 if(g.analysis?.version===2&&Array.isArray(g.analysis.details)){const used=new Set();const details=g.analysis.details.map(d=>{const m=moves[d.ply];if(!m||used.has(d.ply)||!number(d.accuracy,0,100)||!number(d.loss,0,1)||d.fen!==m.before||d.afterFen!==m.after||d.side!==m.color)throw Error('Analisi nel backup incoerente con la partita.');used.add(d.ply);const best=playUci(new Chess(m.before),d.best)?d.best:undefined;return {ply:d.ply,side:m.color,san:m.san,from:m.from,to:m.to,promotion:m.promotion,fen:m.before,afterFen:m.after,loss:d.loss,accuracy:d.accuracy,type:Object.hasOwn(TYPES,d.type)?d.type:'good',theme:['king','fork','pin','hanging','material','position'].includes(d.theme)?d.theme:'position',best}});const expected=g.analysis.coverage==='player'?moves.filter(m=>m.color===g.side):moves;analysis={...restoreAnalysisMetrics(g.analysis,moves),version:2,total:moves.length,method:text(g.analysis.method,300)?g.analysis.method:undefined,details,complete:!!g.analysis.complete&&expected.every(m=>details.some(d=>d.ply===moves.indexOf(m))),coverage:g.analysis.coverage==='player'?'player':'all',methodId:typeof g.analysis.methodId==='string'?g.analysis.methodId.slice(0,60):undefined,at:number(g.analysis.at,0,8640000000000000)?g.analysis.at:Date.now(),checkpoint:restoreCheckpoint(g.analysis.checkpoint,moves)}}
 return {id:g.id,pgn:g.pgn,headers:c.getHeaders(),source:['coach','chess.com','import','live'].includes(g.source)?g.source:'import',side:['w','b'].includes(g.side)?g.side:null,playedAt:number(g.playedAt,0,8640000000000000)?g.playedAt:Date.now(),analysis}});
 if(data.attempts!==undefined&&!Array.isArray(data.attempts))throw Error('Ripassi nel backup non validi.');const attempts=(data.attempts||[]).map(a=>{if(!text(a.id)||!number(a.at,0,8640000000000000)||typeof a.success!=='boolean')throw Error('Tentativo nel backup non valido.');return {id:a.id,cardId:text(a.cardId)?a.cardId:undefined,sessionId:text(a.sessionId)?a.sessionId:undefined,position:text(a.position)?a.position:'',theme:text(a.theme,25)?a.theme:'position',success:a.success,assisted:!!a.assisted,at:a.at,rating:cleanRating(a.rating)}});return {games,attempts,settings:data.version===2&&data.settings?sanitizeSettings(data.settings):undefined,meta:data.version===2?validateMeta(data.meta||[],new Set(games.map(g=>g.id))):[]}}

export function validateMeta(records,gameIds){if(!Array.isArray(records)||records.length>10000)throw Error('Profilo nel backup non valido.');const out=[];const theme=t=>['king','fork','pin','hanging','material','position'].includes(t);for(const m of records){if(!m||!text(m.id))continue;
 if(m.id==='chess-profile'){if(m.disconnected){out.push({id:m.id,disconnected:true});continue}if(!/^[a-z0-9_-]{1,50}$/.test(m.username||''))throw Error('Username nel backup non valido.');const stats={};for(const k of ['chess_rapid','chess_blitz','chess_bullet','chess_daily']){const rating=m.stats?.[k]?.last?.rating;if(number(rating,0,10000))stats[k]={last:{rating}}}out.push({id:m.id,username:m.username,profile:{username:m.username},stats,fetchedAt:number(m.fetchedAt,0,Date.now())?m.fetchedAt:0})}
 else if(/^batch-[a-z0-9_-]{1,50}$/.test(m.id)&&Array.isArray(m.ids)){out.push({id:m.id,ids:[...new Set(m.ids.filter(id=>gameIds.has(id)))],lastSeen:number(m.lastSeen,0,Date.now())?m.lastSeen:null})}
 else if(/^player-report-[a-z0-9_-]{1,50}$/.test(m.id)&&number(m.count,0,50000)&&number(m.total,0,50000)){out.push({id:m.id,count:m.count,total:m.total,theme:theme(m.theme)?m.theme:null})}
 else if(/^weekly-[a-z0-9_-]+-\d+$/.test(m.id)&&number(m.start,0,Date.now())&&theme(m.theme)){const b=m.baseline;if(b&&number(b.moves,0,10000000)&&number(b.errors,0,b.moves)&&number(b.games,0,50000))out.push({id:m.id,start:m.start,theme:m.theme,baseline:{moves:b.moves,errors:b.errors,games:b.games,rate:b.moves?100*b.errors/b.moves:null}})}
 }return out}
